<?php $fieldError=static function(string $field) use ($errors): void { if(isset($errors[$field])) echo '<small class="field-error">'.esc($errors[$field]).'</small>'; }; ?>
<form class="workspace-form" method="post" action="<?= site_url(isset($resource['id'])?'admin/resources/'.$resource['id'].'/edit':'admin/resources') ?>"><?= csrf_field() ?>
<section class="workspace-card"><h2>General Information</h2><div class="workspace-fields"><div><label for="name">Resource name</label><input id="name" name="name" required maxlength="150" value="<?= esc($resource['name']??'','attr') ?>"><?php $fieldError('name') ?></div><div><label for="resource_type">Resource type</label><select id="resource_type" name="resource_type" required><?php foreach(['facility','equipment'] as $type): ?><option value="<?= $type ?>" <?= ($resource['resource_type']??'')===$type?'selected':'' ?>><?= ucfirst($type) ?></option><?php endforeach ?></select><?php $fieldError('resource_type') ?></div><div><label for="category">Category</label><input id="category" name="category" required maxlength="100" value="<?= esc($resource['category']??'','attr') ?>"><small>For example, meeting rooms or audio equipment.</small><?php $fieldError('category') ?></div><div class="workspace-full"><label for="description">Description</label><textarea id="description" name="description" rows="3" maxlength="5000"><?= esc($resource['description']??'') ?></textarea><?php $fieldError('description') ?></div></div></section>
<section class="workspace-card"><h2>Inventory and Location</h2><div class="workspace-fields"><div><label for="location">Location</label><input id="location" name="location" maxlength="150" value="<?= esc($resource['location']??'','attr') ?>"><?php $fieldError('location') ?></div><div><label for="quantity">Quantity</label><input id="quantity" name="quantity" type="number" required min="1" max="4294967295" step="1" value="<?= esc((string)($resource['quantity']??'1'),'attr') ?>"><small>Exactly 1 for a facility; interchangeable stock count for equipment.</small><?php $fieldError('quantity') ?></div><div id="equipment-fields" class="workspace-full workspace-fields" <?= ($resource['resource_type']??'')!=='equipment'?'hidden':'' ?>><div><label for="catalog_group">Borrower catalog group (optional)</label><input id="catalog_group" name="catalog_group" maxlength="100" value="<?= esc($resource['catalog_group']??'','attr') ?>"><small>Matching equipment with the same category, group, and rate is presented together.</small><?php $fieldError('catalog_group') ?></div><div><label for="inventory_identifier">Administrator inventory identifier (optional)</label><input id="inventory_identifier" name="inventory_identifier" maxlength="100" value="<?= esc($resource['inventory_identifier']??'','attr') ?>"><small>Unique per physical inventory record when provided.</small><?php $fieldError('inventory_identifier') ?></div></div></div></section>
<section id="facility-fields" class="workspace-card" <?= ($resource['resource_type']??'')==='equipment'?'hidden':'' ?>><h2>Facility Configuration</h2><div class="workspace-fields"><div id="capacity-field" <?= ($resource['resource_type']??'')==='equipment'?'hidden':'' ?>><label for="capacity">Facility capacity (optional)</label><input id="capacity" name="capacity" type="number" min="1" max="4294967295" step="1" <?= ($resource['resource_type']??'')==='equipment'?'disabled':'' ?> value="<?= esc((string)($resource['capacity']??''),'attr') ?>"><small>If entered, use a positive number of people.</small><?php $fieldError('capacity') ?></div><div><label for="conflict_groups">Mutually exclusive facility configurations (optional)</label><input id="conflict_groups" name="conflict_groups" maxlength="165" value="<?= esc($resource['conflict_groups']??'','attr') ?>"><small>Comma-separated group keys; known gym/lounge alternatives use safe defaults.</small><?php $fieldError('conflict_groups') ?></div></div></section>
<section class="workspace-card"><h2>Pricing and Operational Status</h2><div class="workspace-fields"><div><label for="rate_per_hour">Rate per hour, per unit (PHP)</label><input id="rate_per_hour" name="rate_per_hour" type="number" min="0" max="99999999.99" step="0.01" value="<?= esc((string)($resource['rate_per_hour']??''),'attr') ?>"><small>Leave blank for a matching provisional preset, or enter a rate with up to two decimal places.</small><?php $fieldError('rate_per_hour') ?></div><div><label for="status">Operational status</label><select id="status" name="status" required><?php foreach(['available','unavailable','maintenance'] as $status): ?><option value="<?= $status ?>" <?= ($resource['status']??'')===$status?'selected':'' ?>><?= ucfirst($status) ?></option><?php endforeach ?></select><?php $fieldError('status') ?></div><details class="workspace-full"><summary>Provisional suggested rates (PHP/hour)</summary><div class="workspace-fields"><div><h3>Facilities</h3><ul><?php foreach($pricing->facilityRates as $name=>$rate): ?><li><?= esc($name) ?> — <?= esc($rate) ?></li><?php endforeach ?></ul></div><div><h3>Equipment (per unit)</h3><ul><?php foreach($pricing->equipmentRates as $name=>$rate): ?><li><?= esc($name) ?> — <?= esc($rate) ?></li><?php endforeach ?></ul></div></div><small>These are provisional student-friendly rates, not official rental fees. Administrators may edit every rate.</small></details></div></section>
<div class="workspace-actions"><a class="button secondary" href="<?= site_url('admin/resources') ?>">Cancel</a><button type="submit">Save resource</button></div></form><script src="<?= base_url('js/resource-form.js') ?>" defer></script>
